A \emph{field} is a commutative ring with unity $(F, +, \cdot)$
satisfying:

\begin{enumerate}[label=\textbf{F\arabic*.}]
 \item \textbf{Additive abelian group.}
 $(F, +)$ is an abelian group with identity $0$.

 \item \textbf{Multiplicative abelian group on nonzero elements.}
 $(F \setminus \{0\}, \cdot)$ is an abelian group with identity $1$.
 Explicitly: for each $a \in F$ with $a \neq 0$, there exists
 $a^{-1} \in F$ such that $a \cdot a^{-1} = 1$.

 \item \textbf{Distributivity.}
 $a \cdot (b + c) = a \cdot b + a \cdot c$
 for all $a, b, c \in F$.

 \item \textbf{Non-triviality.}
 $0 \neq 1$.
\end{enumerate}

Let $f : A \to B$, $S \subseteq A$, $T \subseteq B$.
 \begin{itemize}
 \item \textbf{Image of $f$}:
 $\displaystyle\operatorname{Im}(f) = f(A) = \{\,f(a) : a \in A\,\}
 \subseteq B$.
 \item \textbf{Image of a subset} $S$:
 $\displaystyle f(S) = \{\,f(s) : s \in S\,\} \subseteq B$.
 \item \textbf{Preimage of a subset} $T$:
 $\displaystyle f^{-1}(T) = \{\,a \in A : f(a) \in T\,\} \subseteq A$.
 \end{itemize}
 Note: $f^{-1}(T)$ is defined for every function $f$; it does \emph{not}
 require $f$ to be invertible.

