A \emph{ring} is a triple $(R, +, \cdot)$ where $R$ is a set and
$+$ and $\cdot$ are binary operations on $R$ satisfying:

\begin{enumerate}[label=\textbf{R\arabic*.}]
 \item \textbf{Additive abelian group.}
 $(R, +)$ is an abelian group:
 \begin{itemize}
 \item $(a + b) + c = a + (b + c)$ for all $a,b,c \in R$.
 \item $a + b = b + a$ for all $a, b \in R$.
 \item There exists $0 \in R$ such that $a + 0 = a$ for all $a \in R$.
 \item For each $a \in R$, there exists $-a \in R$ such that
 $a + (-a) = 0$.
 \end{itemize}

 \item \textbf{Multiplicative associativity.}
 $(a \cdot b) \cdot c = a \cdot (b \cdot c)$
 for all $a, b, c \in R$.

 \item \textbf{Distributivity.}
 \begin{itemize}
 \item $a \cdot (b + c) = a \cdot b + a \cdot c$
 for all $a,b,c \in R$.
 \item $(a + b) \cdot c = a \cdot c + b \cdot c$
 for all $a,b,c \in R$.
 \end{itemize}
\end{enumerate}

Let $(P, \leq_P)$ and $(Q, \leq_Q)$ be finite partially ordered sets and
let $\varphi : P \to Q$ be a bijection. The following are equivalent:
\begin{enumerate}
 \item $\varphi$ is an order-isomorphism.
 \item For all $x, y \in P$:\; $x <_P y \;\Longleftrightarrow\; \varphi(x) <_Q \varphi(y)$.
 \item For all $x, y \in P$:\; $x \prec_P y \;\Longleftrightarrow\; \varphi(x) \prec_Q \varphi(y)$.
\end{enumerate}

A relation $\leq$ on a set $S$ is a \emph{partial order} if it satisfies,
for all $a, b, c \in S$:
\begin{enumerate}
 \item \textbf{Reflexivity:} $a \leq a$.
 \item \textbf{Anti-symmetry:} $a \leq b \land b \leq a \Longrightarrow a = b$.
 \item \textbf{Transitivity:} $a \leq b \land b \leq c \Longrightarrow a \leq c$.
\end{enumerate}
The pair $(S, \leq)$ is called a \emph{partially ordered set}, or \emph{poset}.

A relation $<$ on a set $S$ is a \emph{strict partial order} if it satisfies,
for all $a, b, c \in S$:
\begin{enumerate}
 \item \textbf{Irreflexivity:} $\neg(a < a)$.
 \item \textbf{Asymmetry:} $a < b \Longrightarrow \neg(b < a)$.
 \item \textbf{Transitivity:} $a < b \land b < c \Longrightarrow a < c$.
\end{enumerate}

